head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > removeData]<br/>지정한 키로 등록된 사용자 데이터를 WebSquare 에서 제거합니다.",
    "validation" : [
        "key(필수) 파라미터로 삭제할 데이터의 Key 값을 설정할 수 있어야 합니다.",
        "지정한 키로 등록된 데이터를 제거해야 합니다.",
        "데이터가 객체인 경우 하위 속성을 삭제한 후 키 자체도 제거합니다.",
        "데이터가 객체인 경우 해당 객체를 다른 곳에서 참조하고 있으면 빈 객체가 됩니다.",
    ]
}

// 외부 참조용 변수
scwin.refObj = null;

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // setData 로 테스트 데이터 등록
    scwin.refObj = {name: "참조객체", value: 200};
    WebSquare.util.setData("item1", {name: "테스트", value: 100});
    WebSquare.util.setData("item2", "문자열데이터");
    WebSquare.util.setData("item3", scwin.refObj);

    $c.gcm.createLabel('label="setData 등록: item1(Object), item2(String), item3(Object-외부참조)"', '', 'label1');
};



scwin.btn_removeData_onclick = function () {
    let key = par_key.getValue();

    // 제거 전 getData 로 확인
    let beforeData = WebSquare.util.getData(key);
    wf_body_bottom.getObj("scwin").setReturnValue("제거 전 getData('" + key + "') : " + JSON.stringify(beforeData));

    // removeData 실행
    WebSquare.util.removeData(key);

    // 제거 후 getData 로 확인
    let afterData = WebSquare.util.getData(key);
    wf_body_bottom.getObj("scwin").setReturnValue("제거 후 getData('" + key + "') : " + JSON.stringify(afterData));

    // item3 인 경우 외부 참조 객체 상태 확인
    if (key === "item3") {
        wf_body_bottom.getObj("scwin").setReturnValue("외부 참조 객체(scwin.refObj) : " + JSON.stringify(scwin.refObj));
    }
}
